      value => settle({ kind: "return", value }),
      reason => settle(frame.report && Object.is(frame.report.origin.signal.reason, reason)
        ? { kind: "throw", reason, report: frame.report }
        : { kind: "throw", reason }),
    );
    if (settled) void raw.catch(() => undefined);
  });
}

